style.css:
@-moz-document domain("youtube.com") {
:root { color-scheme: dark !important; }

html, body, ytd-app {
  background-color: #08070b !important;
  color: #eeeaf1 !important;
}
ytd-app {
  background-image:
    repeating-radial-gradient(circle at 0 0, transparent 0 27px, rgba(238,234,241,.72) 28px 29px, transparent 30px 55px),
    repeating-conic-gradient(from 0deg at 0 0, transparent 0deg 14deg, rgba(238,234,241,.58) 14.4deg 14.9deg, transparent 15.3deg 30deg) !important;
  background-size: 230px 230px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
}

/* Transparent page layers reveal the web pattern in the gaps. */
ytd-page-manager, ytd-browse, ytd-search,
ytd-two-column-browse-results-renderer, ytd-rich-grid-renderer,
#contents, #primary, #secondary, #columns {
  background: transparent !important;
}

/* Top bar */
#masthead, #masthead-container, ytd-masthead {
  background: #08070b !important;
  border-bottom: 1px solid #493451 !important;
  box-shadow: 0 3px 14px rgba(0,0,0,.65) !important;
}
#logo, #logo-icon, ytd-topbar-logo-renderer {
  filter: grayscale(1) brightness(1.7) !important;
}

/* Violet search frame, dark interior */
ytd-searchbox, #container.ytd-searchbox, #search-form {
  background: #17111e !important;
  border: 1px solid #79558e !important;
  border-radius: 24px !important;
}
#search, #search-input, #search-input input, ytd-searchbox input {
  color: #f1edf3 !important;
  background: #100d14 !important;
}
#search-icon-legacy, #search-icon-legacy yt-icon, ytd-searchbox #search-icon {
  color: #c2a3d5 !important;
  fill: #c2a3d5 !important;
}
#voice-search-button { background: #21182a !important; color: #d9c7e5 !important; }

/* Left navigation */
ytd-guide-renderer, ytd-mini-guide-renderer, #guide-content,
ytd-guide-section-renderer {
  background: #100e14 !important;
  color: #eeeaf1 !important;
}
ytd-guide-entry-renderer, ytd-mini-guide-entry-renderer {
  color: #e8e2eb !important;
  border-radius: 9px !important;
}
ytd-guide-entry-renderer:hover, ytd-mini-guide-entry-renderer:hover,
ytd-guide-entry-renderer[active] { background: #2b2033 !important; }
ytd-guide-entry-renderer yt-icon, ytd-mini-guide-entry-renderer yt-icon {
  color: #b99acb !important;
}

/* Dark category strip and violet chips */
ytd-feed-filter-chip-bar-renderer, #chips-wrapper, ytd-chip-cloud-renderer {
  background: #0b090e !important;
  border-bottom: 1px solid #33263b !important;
}
yt-chip-cloud-chip-renderer, yt-chip-cloud-chip-renderer[chip-style],
yt-chip-cloud-chip-renderer #chip, yt-chip-cloud-chip-renderer yt-formatted-string {
  background: #211a27 !important;
  color: #e9e1ed !important;
  border-color: #594267 !important;
  border-radius: 5px !important;
}
yt-chip-cloud-chip-renderer[selected],
yt-chip-cloud-chip-renderer[aria-selected="true"] {
  background: #60416f !important;
  color: #fff !important;
}

/* Individual video cards: charcoal, subtle border, soft separation */
ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer,
ytd-compact-video-renderer, ytd-playlist-renderer {
  background: #15121a !important;
  border: 1px solid #302638 !important;
  border-radius: 12px !important;
  padding: 5px !important;
  box-shadow: 0 5px 16px rgba(0,0,0,.35) !important;
}
ytd-rich-item-renderer:hover, ytd-video-renderer:hover,
  ytd-grid-video-renderer:hover {
  background: #201827 !important;
  border-color: #79558e !important;
}
#video-title, .title, .yt-core-attributed-string, #channel-name,
#owner-text, ytd-channel-name { color: #eeeaf1 !important; }
#metadata-line, ytd-video-meta-block, .secondary, .inline-metadata-item {
  color: #aaa0b0 !important;
}

/* Menus and dialogs */
ytd-menu-popup-renderer, tp-yt-paper-listbox, ytd-popup-container,
ytd-multi-page-menu-renderer, tp-yt-paper-dialog,
ytd-consent-bump-v2-lightbox {
  background: #17131c !important;
  color: #eeeaf1 !important;
  border: 1px solid #594267 !important;
}

/* Buttons and accents */
yt-button-shape button, ytd-button-renderer button, button {
  color: #eeeaf1 !important;
  border-color: #594267 !important;
}
yt-button-shape button:hover, ytd-button-renderer button:hover, button:hover {
  background-color: #35263e !important;
}
a, a yt-formatted-string { color: #c9afd9 !important; }

/* Comments and fields */
ytd-comments, ytd-comment-thread-renderer, ytd-comment-view-model {
  color: #eeeaf1 !important;
}
#placeholder-area, #contenteditable-root, textarea {
  background: #17111e !important;
  color: #eeeaf1 !important;
  border-color: #79558e !important;
}

/* Player progress */
.ytp-play-progress, .ytp-swatch-background-color,
.ytp-volume-slider-handle, .ytp-scrubber-button {
  background: #b99acb !important;
}

/* Scrollbars and focus */
* { scrollbar-color: #76518a #0b090e; }
*:focus-visible { outline: 2px solid #b99acb !important; outline-offset: 2px !important; }
}
